pub enum LAGr_TriangleCount_Method {
    #[doc = "< auto selection of method"]
    LAGr_TriangleCount_AutoMethod = 0,
    #[doc = "< sum (sum ((A^2) .* A)) / 6"]
    LAGr_TriangleCount_Burkhardt = 1,
    #[doc = "< sum (sum ((L * U) .* A)) / 2"]
    LAGr_TriangleCount_Cohen = 2,
    #[doc = "< sum (sum ((L * L) .* L))"]
    LAGr_TriangleCount_Sandia_LL = 3,
    #[doc = "< sum (sum ((U * U) .* U))"]
    LAGr_TriangleCount_Sandia_UU = 4,
    #[doc = "< sum (sum ((L * U') .* L))"]
    LAGr_TriangleCount_Sandia_LUT = 5,
    #[doc = "< sum (sum ((U * L') .* U))"]
    LAGr_TriangleCount_Sandia_ULT = 6,
}
#[repr(i32)]
#[doc = " LAGr_TriangleCount_Presort: an enum to control if/how the matrix is sorted\n prior to counting triangles."]
#[derive(Debug, Copy, Clone, Hash, PartialEq, Eq)]
pub enum LAGr_TriangleCount_Presort {
    #[doc = "< no sort"]
    LAGr_TriangleCount_NoSort = 2,
    #[doc = "< sort by degree, ascending."]
    LAGr_TriangleCount_Ascending = 1,
    #[doc = "< sort by degree, descending."]
    LAGr_TriangleCount_Descending = -1,
    #[doc = "< auto selection of presort:\n< No presort is done for the Burkhardt or Cohen methods, and\n< no sort is done for the Sandia_* methods if the sampled mean\n< out-degree is <= 4 * the sample median out-degree.\n< Otherwise: sort in ascending order for Sandia_LL and Sandia_LUT,\n< descending ordering for Sandia_UU and Sandia_ULT.  On output,\n< presort is modified to reflect the sorting method used (NoSort,\n< Ascending, or Descending)."]
    LAGr_TriangleCount_AutoSort = 0,
}
